from comp_areas import *
C=[
 ("groups","Dedičské konania a spory o dedičstvo",["Poskytujeme právnu pomoc v dedičských konaniach vrátane dodatočných konaní o dedičstve, ak sa po skončení pôvodného konania zistí ďalší majetok poručiteľa.","Pomáhame pri riešení sporných otázok medzi dedičmi, preverovaní vlastníckych vzťahov k zdedenému majetku a pri uplatňovaní práv súvisiacich s dedičstvom."],"books_pen"),
 ("payments","Náhrada škody",["Posudzujeme nároky na náhradu škody vzniknutej porušením právnych povinností, poškodením majetku alebo iným protiprávnym konaním.","Zastupujeme poškodených pri uplatňovaní ich nárokov, ako aj osoby, voči ktorým sú nároky na náhradu škody uplatňované. Súčasťou právnej pomoci je posúdenie zodpovednosti za škodu, jej rozsahu a možností mimosúdneho a súdneho riešenia."],"jar"),
 ("home","Bezdôvodné obohatenie",["Bezdôvodné obohatenie môže vzniknúť napríklad užívaním cudzej nehnuteľnosti bez právneho dôvodu, prijatím plnenia bez právneho titulu alebo plnením z právneho dôvodu, ktorý následne odpadol.","V týchto prípadoch posudzujeme vznik a rozsah nároku na vydanie bezdôvodného obohatenia a zastupujeme klientov pri jeho uplatňovaní alebo obrane proti nemu."],"house"),
 ("diversity_1","Zrušenie a vyporiadanie bezpodielového spoluvlastníctva manželov",["Poskytujeme právne služby pri zrušení a vyporiadaní bezpodielového spoluvlastníctva manželov (BSM), najmä pri usporiadaní vlastníckych vzťahov k nehnuteľnostiam, finančným prostriedkom, záväzkom a ďalšiemu spoločnému majetku.","Pripravujeme dohody o vyporiadaní BSM a zastupujeme klientov pri rokovaniach aj v súdnych konaniach, ak sa manželia na vyporiadaní nedohodnú."],"rings"),
]
cards=[card_side(*c) for c in C]
