grid='<div class="grid gap-5 lg:grid-cols-2 lg:gap-6">'+"".join(cards[:4])+'</div><div class="mt-5 lg:mt-6">'+card_side("description","Ďalšie občianskoprávne záležitosti",["Poskytujeme právnu pomoc aj pri ďalších otázkach občianskeho práva, najmä pri ochrane vlastníckych a iných majetkových práv, riešení sporov zo zmluvných vzťahov a uplatňovaní alebo obrane proti občianskoprávnym nárokom.","Rozsah právnej pomoci závisí od povahy konkrétneho prípadu a právnych otázok, ktoré je potrebné vyriešiť."],"books_row")+'</div>'
